//! Batched renaming of tracked exports. The journal restores unfinished batches.
use std::{fs,path::{Path,PathBuf},thread,time::Duration};
use serde_json::{Value,json};
use crate::studio_files as disk;
pub(crate) struct Unlock(PathBuf);impl Drop for Unlock{fn drop(&mut self){let _=fs::remove_file(self.0.join("owner"));let _=fs::remove_dir(&self.0);}}
fn alive(pid:u32)->bool{
 #[cfg(unix)]{std::process::Command::new("kill").args(["-0",&pid.to_string()]).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).status().map(|s|s.success()).unwrap_or(true)}
 #[cfg(windows)]{std::process::Command::new("tasklist").args(["/FI",&format!("PID eq {pid}"),"/NH"]).output().map(|o|String::from_utf8_lossy(&o.stdout).split_whitespace().any(|s|s==pid.to_string())).unwrap_or(true)}
 #[cfg(not(any(unix,windows)))]{true}
}
pub(crate) fn lock(root:&Path)->Result<Unlock,String>{let path=disk::subdir(root,"Studio Link")?.join(".workflow.lock");for _ in 0..100{if fs::create_dir(&path).is_ok(){fs::write(path.join("owner"),std::process::id().to_string()).map_err(|e|e.to_string())?;return Ok(Unlock(path))}if let Some(pid)=fs::read_to_string(path.join("owner")).ok().and_then(|s|s.parse::<u32>().ok()){if !alive(pid){let _=fs::remove_file(path.join("owner"));let _=fs::remove_dir(&path);continue;}}thread::sleep(Duration::from_millis(20));}Err("FolderExporter or Storyboard Studio is saving. Wait for that export to finish, then retry.".into())}

fn load(path:&Path,default:Value)->Result<Value,String>{if !path.exists(){return Ok(default)}serde_json::from_slice(&fs::read(path).map_err(|e|e.to_string())?).map_err(|e|e.to_string())}
fn save(root:&Path,name:&str,v:&Value)->Result<(),String>{disk::atomic_json(&disk::subdir(root,"Studio Link")?,name,&v.to_string())}
fn safe(root:&Path,rel:&str)->Result<PathBuf,String>{let target=root.join(disk::relative(rel)?);let mut parent=target.parent();while let Some(p)=parent{if p.exists(){if !p.canonicalize().map_err(|e|e.to_string())?.starts_with(root){return Err("A managed folder points outside the project".into())}break}parent=p.parent();}if fs::symlink_metadata(&target).map(|m|m.file_type().is_symlink()).unwrap_or(false){return Err("A managed file is a symbolic link".into())}Ok(target)}
fn recover(root:&Path)->Result<(),String>{let link=disk::subdir(root,"Studio Link")?;let journal=link.join("organization-journal.json");if !journal.exists(){return Ok(())}let j=load(&journal,json!({}))?;let moves=j["moves"].as_array().ok_or("Invalid organization recovery journal")?;if j["phase"]=="committed"{for m in moves.iter().filter(|m|m["deduplicate"]==true){let stage=safe(root,m["stage"].as_str().ok_or("Missing duplicate stage")?)?;if stage.exists(){let to=safe(root,m["to"].as_str().ok_or("Missing duplicate destination")?)?;if crate::owned_output::file_fingerprint(&stage)?!=crate::owned_output::file_fingerprint(&to)?{return Err("A preserved duplicate changed during recovery. Both files were kept.".into())}fs::remove_file(stage).map_err(|e|e.to_string())?;}}fs::remove_file(journal).map_err(|e|e.to_string())?;return Ok(())}
 // Return all installed destinations to staging first: rename cycles remain reversible.
 if j["phase"]=="installing"{for m in moves.iter().filter(|m|m["deduplicate"]!=true){let stage=safe(root,m["stage"].as_str().ok_or("Missing recovery stage")?)?;let to=safe(root,m["to"].as_str().ok_or("Missing recovery target")?)?;if !stage.exists()&&to.exists(){fs::rename(to,stage).map_err(|e|e.to_string())?;}}}
 for m in moves{let stage=safe(root,m["stage"].as_str().unwrap())?;let from=safe(root,m["from"].as_str().ok_or("Missing recovery source")?)?;if stage.exists(){if from.exists(){return Err("Recovery source is occupied. Keep the app open and restore the organization journal.".into())}if let Some(p)=from.parent(){fs::create_dir_all(p).map_err(|e|e.to_string())?;}fs::rename(stage,from).map_err(|e|e.to_string())?;}}
 if let Some(docs)=j["documents"].as_object(){for(name,v)in docs{save(root,name,v)?;}}fs::remove_file(journal).map_err(|e|e.to_string())?;Ok(())}
fn organize(directory:String,project:String,moves:Vec<Value>)->Result<Value,String>{let root=disk::root(&directory)?;let _lock=lock(&root)?;recover(&root)?;crate::folder_rename::recover(&root)?;let link=disk::subdir(&root,"Studio Link")?;let manifest=load(&link.join("project.json"),json!({}))?;if manifest["project"]["id"]!=project{return Err("Project folder belongs to another project".into())}let mut outputs=load(&link.join("storyboard-outputs.json"),json!({"format":"storyboard-outputs-v1","files":{}}))?;let mut catalog=load(&link.join("media-index.json"),json!({"format":"studio-media-index-v1","schemaVersion":1,"projectId":project,"entries":{}}))?;
 if catalog["projectId"]!=project{return Err("Media catalog belongs to another project".into())}if moves.len()>20000{return Err("Too many file changes in one batch".into())}
 let mut froms=std::collections::HashSet::new();let mut tos=std::collections::HashSet::new();let mut list=Vec::new();let mut missing=Vec::new();for mut m in moves{let from=m["from"].as_str().ok_or("Missing old filename")?.to_string();let to=m["to"].as_str().ok_or("Missing new filename")?.to_string();if from==to{continue}let a=safe(&root,&from)?;safe(&root,&to)?;if !tos.insert(to.to_lowercase()){return Err("Two tracked files use the same new name. Change the naming patterns.".into())}let shadowed=m["type"]=="storyboard"&&catalog["entries"].as_object().into_iter().flat_map(|e|e.values()).filter(|e|e["removed"]!=true).flat_map(|e|e["files"].as_array().into_iter().flatten().chain(e["referenceFiles"].as_array().into_iter().flatten())).any(|f|f["relativePath"]==from);if !a.exists()||shadowed{if m["type"]=="storyboard"&&outputs["files"][&from]["project"]==project{outputs["files"].as_object_mut().unwrap().remove(&from);}missing.push(m);continue}if !froms.insert(from.clone()){return Err("Two file records claim the same original location. Refresh before renaming.".into())}
 let owns=if m["type"]=="storyboard"{outputs["files"][&from]["project"]==project&&outputs["files"][&from]["key"].as_str().map(|k|if let Some(expected)=m["ownerKey"].as_str(){k==expected}else{k==format!("export:{from}")||[m["cardId"].as_str(),m["sourceCardId"].as_str()].into_iter().flatten().any(|id|k.starts_with(&format!("drawing:{id}:")))}).unwrap_or(false)}else{let key=m["entryKey"].as_str().ok_or("Missing cleanup identity")?;catalog["entries"][key]["files"].as_array().into_iter().flatten().chain(catalog["entries"][key]["referenceFiles"].as_array().into_iter().flatten()).chain(catalog["entries"][key]["ignoredFiles"].as_array().into_iter().flatten()).any(|f|f["relativePath"]==from&&f["id"]==m["fileId"]&&f["managed"]==true)};if !owns{return Err(format!("{from} is not a tracked app-managed file. Refresh before renaming."))}
 m["stage"]=json!(format!("Studio Link/.organization-{}-{}.tmp",std::process::id(),list.len()));if safe(&root,m["stage"].as_str().unwrap())?.exists(){return Err("An unfinished file organization requires recovery".into())}list.push(m);}
 for m in &mut list{let to=m["to"].as_str().unwrap();let target=safe(&root,to)?;if target.exists()&&!froms.contains(to){let source=safe(&root,m["from"].as_str().unwrap())?;let expected=catalog["entries"][m["entryKey"].as_str().unwrap_or("")]["ignoredFiles"].as_array().into_iter().flatten().find(|f|f["id"]==m["fileId"]&&f["relativePath"]==m["from"]).and_then(|f|f["fingerprint"].as_str());let another_active=catalog["entries"].as_object().into_iter().flat_map(|e|e.values()).filter(|e|e["removed"]!=true).flat_map(|e|e["files"].as_array().into_iter().flatten().chain(e["referenceFiles"].as_array().into_iter().flatten())).any(|f|f["relativePath"]==to);if m["type"]=="cleanup"&&m["inactive"]==true&&!another_active&&expected.is_some()&&Some(crate::owned_output::file_fingerprint(&source)?.as_str())==expected&&Some(crate::owned_output::file_fingerprint(&target)?.as_str())==expected{m["deduplicate"]=json!(true);}else{return Err(format!("Cannot rename to {to}: an existing file already uses that location. Choose distinct naming patterns."))}}}
 for m in &missing{let to=m["to"].as_str().unwrap();if safe(&root,to)?.exists()&&!froms.contains(to){return Err(format!("Cannot rename to {to}: an existing file already uses that location. Choose distinct naming patterns."))}}
 for m in &missing{if m["type"]=="cleanup"{if let Some(e)=catalog["entries"].get_mut(m["entryKey"].as_str().unwrap_or("")){for field in ["files","referenceFiles","ignoredFiles"]{if let Some(files)=e[field].as_array_mut(){for f in files{if f["id"]==m["fileId"]{f["relativePath"]=m["to"].clone();f["path"]=json!(root.join(m["to"].as_str().unwrap()).to_string_lossy());f["missing"]=json!(true);f["state"]=json!("missing");}}}}}}}
 if list.is_empty(){if !missing.is_empty(){save(&root,"media-index.json",&catalog)?;save(&root,"storyboard-outputs.json",&outputs)?;}return Ok(json!({"moves":[],"missing":missing,"outputs":outputs["files"],"catalog":catalog}))}
 let mut documents=serde_json::Map::new();documents.insert("project.json".into(),manifest.clone());documents.insert("storyboard-outputs.json".into(),outputs.clone());documents.insert("media-index.json".into(),catalog.clone());
 for entry in fs::read_dir(&link).map_err(|e|e.to_string())?{let path=entry.map_err(|e|e.to_string())?.path();let name=path.file_name().unwrap_or_default().to_string_lossy().to_string();if name.starts_with("folderexporter-index")&&name.ends_with(".json"){documents.insert(name,load(&path,json!({}))?);}}
 save(&root,"organization-journal.json",&json!({"moves":list,"documents":documents,"phase":"staging"}))?;
 let result=(||->Result<(),String>{
 for m in &list{fs::rename(safe(&root,m["from"].as_str().unwrap())?,safe(&root,m["stage"].as_str().unwrap())?).map_err(|e|e.to_string())?;}
 save(&root,"organization-journal.json",&json!({"moves":list,"documents":documents,"phase":"installing"}))?;
 for m in list.iter().filter(|m|m["deduplicate"]!=true){let to=m["to"].as_str().unwrap();let parent=Path::new(to).parent().unwrap();disk::subdir(&root,&parent.to_string_lossy())?;fs::rename(safe(&root,m["stage"].as_str().unwrap())?,safe(&root,to)?).map_err(|e|e.to_string())?;}
 let mapping:std::collections::HashMap<String,String>=list.iter().map(|m|(m["from"].as_str().unwrap().into(),m["to"].as_str().unwrap().into())).collect();
 let previous=outputs["files"].clone();for m in &list{outputs["files"].as_object_mut().unwrap().remove(m["from"].as_str().unwrap());}for m in &list{let from=m["from"].as_str().unwrap();let to=m["to"].as_str().unwrap();if let Some(record)=previous.get(from).filter(|_|m["type"]=="storyboard"){let mut r=record.clone();let(size,modified)=disk::metadata(&root.join(to))?;r["size"]=json!(size);r["modified"]=json!(modified);outputs["files"][to]=r;}}
 if let Some(entries)=catalog["entries"].as_object_mut(){for e in entries.values_mut(){let mut changed=false;for field in ["files","referenceFiles","ignoredFiles"]{if let Some(files)=e[field].as_array_mut(){for f in files{if let Some(to)=f["relativePath"].as_str().and_then(|p|mapping.get(p)){f["relativePath"]=json!(to);f["path"]=json!(root.join(to).to_string_lossy());f["name"]=json!(Path::new(to).file_name().unwrap_or_default().to_string_lossy());changed=true;}}}}if changed{e["revision"]=json!(format!("organized-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos()));}}}
 let mut updated_manifest=manifest.clone();if let Some(records)=updated_manifest["storyboards"].as_object_mut(){for r in records.values_mut(){if let Some(to)=r["relativePath"].as_str().and_then(|p|mapping.get(p)){r["relativePath"]=json!(to);r["path"]=json!(root.join(to).to_string_lossy());}}}
 for(name,doc)in &documents{if !name.starts_with("folderexporter-index"){continue}let mut doc=doc.clone();if let Some(frames)=doc["frames"].as_array_mut(){for frame in frames{if let Some(files)=frame["files"].as_array_mut(){for f in files{if let Some(to)=f["path"].as_str().and_then(|p|mapping.get(p)){f["path"]=json!(to);f["filename"]=json!(Path::new(to).file_name().unwrap_or_default().to_string_lossy());}}}}}doc["pathRevision"]=json!(format!("organized-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos()));save(&root,name,&doc)?;}
 save(&root,"storyboard-outputs.json",&outputs)?;save(&root,"media-index.json",&catalog)?;save(&root,"project.json",&updated_manifest)?;save(&root,"organization-journal.json",&json!({"moves":list,"documents":documents,"phase":"committed"}))?;Ok(())})();
 if let Err(e)=result{recover(&root).map_err(|r|format!("{e}; recovery needs attention: {r}"))?;return Err(e)}recover(&root)?;for m in &list{if let Some(parent)=root.join(m["from"].as_str().unwrap()).parent(){if parent!=root&&parent!=link{let _=fs::remove_dir(parent);}}}Ok(json!({"moves":list,"missing":missing,"outputs":outputs["files"],"catalog":catalog}))}
#[tauri::command]pub async fn organize_project_media(directory:String,project_id:String,moves:Vec<Value>)->Result<Value,String>{tauri::async_runtime::spawn_blocking(move||organize(directory,project_id,moves)).await.map_err(|e|e.to_string())?}
#[tauri::command]pub fn resolve_storyboard_collision(directory:String,project_id:String,relative_path:String,owner_key:String,choice:String)->Result<String,String>{let root=disk::root(&directory)?;let _lock=lock(&root)?;let manifest=load(&disk::subdir(&root,"Studio Link")?.join("project.json"),json!({}))?;if manifest["project"]["id"]!=project_id{return Err("Project folder belongs to another project".into())}let mut r=load(&disk::subdir(&root,"Studio Link")?.join("storyboard-outputs.json"),json!({"format":"storyboard-outputs-v1","files":{}}))?;let target=safe(&root,&relative_path)?;if !relative_path.ends_with(".png")||!owner_key.starts_with("drawing:"){return Err("Only storyboard PNG exports can be replaced here".into())}let catalog=load(&disk::subdir(&root,"Studio Link")?.join("media-index.json"),json!({}))?;if catalog["entries"].as_object().into_iter().flat_map(|m|m.values()).flat_map(|e|e["files"].as_array().into_iter().flatten()).any(|f|f["relativePath"]==relative_path){return Err("This location contains a cleanup. Export the rough into its storyboard archive instead.".into())}if choice=="keep"{let stem=target.file_stem().unwrap_or_default().to_string_lossy();let parent=Path::new(&relative_path).parent().unwrap();for i in 2..10000{let rel=parent.join(format!("{stem}_{i}.png")).to_string_lossy().replace('\\',"/");if !safe(&root,&rel)?.exists(){return Ok(rel)}}return Err("Too many copies".into())}if choice!="replace"{return Err("Export cancelled".into())}let(size,modified)=if target.exists(){disk::metadata(&target)?}else{(0,0)};r["files"][&relative_path]=json!({"project":project_id,"key":owner_key,"size":size,"modified":modified});save(&root,"storyboard-outputs.json",&r)?;Ok(relative_path)}

#[tauri::command]pub fn snapshot_project_media(directory:String,project_id:String)->Result<Value,String>{let root=disk::root(&directory)?;let _lock=lock(&root)?;recover(&root)?;crate::folder_rename::recover(&root)?;let link=disk::subdir(&root,"Studio Link")?;let manifest=load(&link.join("project.json"),json!({}))?;if manifest["project"]["id"]!=project_id{return Err("Project folder belongs to another project".into())}let catalog=load(&link.join("media-index.json"),json!({"format":"studio-media-index-v1","schemaVersion":1,"projectId":project_id,"entries":{}}))?;let outputs=load(&link.join("storyboard-outputs.json"),json!({"files":{}}))?;Ok(json!({"naming":manifest["naming"],"namingRevision":manifest["namingRevision"],"chapterDirectories":manifest["chapterDirectories"],"storyboards":manifest["storyboards"],"catalog":catalog,"outputs":outputs["files"]}))}

#[cfg(test)]mod tests{use super::*;
fn temp()->PathBuf{let root=std::env::temp_dir().join(format!("ss-organize-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(root.join("Studio Link")).unwrap();save(&root,"project.json",&json!({"project":{"id":"p"},"storyboards":{}})).unwrap();root.canonicalize().unwrap()}
fn rough(root:&Path,path:&str,bytes:&[u8],id:&str){crate::owned_output::write(root,path,bytes,"p",&format!("drawing:{id}:0")).unwrap();}
#[test]fn swaps_managed_names_without_overwriting_or_retargeting(){let r=temp();rough(&r,"Ch/1.png",b"first","one");rough(&r,"Ch/2.png",b"second","two");let result=organize(r.to_string_lossy().into_owned(),"p".into(),vec![json!({"from":"Ch/1.png","to":"Ch/2.png","type":"storyboard","cardId":"one"}),json!({"from":"Ch/2.png","to":"Ch/1.png","type":"storyboard","cardId":"two"})]).unwrap();assert_eq!(fs::read(r.join("Ch/1.png")).unwrap(),b"second");assert_eq!(result["outputs"]["Ch/2.png"]["key"],"drawing:one:0");assert!(!r.join("Studio Link/organization-journal.json").exists());fs::remove_dir_all(r).unwrap();}
#[test]fn rejects_unowned_files_and_keeps_originals(){let r=temp();rough(&r,"Ch/1.png",b"rough","one");fs::write(r.join("Ch/occupied.png"),b"custom").unwrap();assert!(organize(r.to_string_lossy().into_owned(),"p".into(),vec![json!({"from":"Ch/1.png","to":"Ch/occupied.png","type":"storyboard","cardId":"one"})]).is_err());assert_eq!(fs::read(r.join("Ch/1.png")).unwrap(),b"rough");assert_eq!(fs::read(r.join("Ch/occupied.png")).unwrap(),b"custom");fs::remove_dir_all(r).unwrap();}
#[test]fn recovers_partially_staged_batch_without_moving_untouched_destinations(){let r=temp();rough(&r,"Ch/1.png",b"one","one");rough(&r,"Ch/2.png",b"two","two");let moves=json!([{"from":"Ch/1.png","to":"Ch/2.png","stage":"Studio Link/.one.tmp"},{"from":"Ch/2.png","to":"Ch/1.png","stage":"Studio Link/.two.tmp"}]);save(&r,"organization-journal.json",&json!({"phase":"staging","moves":moves,"documents":{}})).unwrap();fs::rename(r.join("Ch/1.png"),r.join("Studio Link/.one.tmp")).unwrap();recover(&r).unwrap();assert_eq!(fs::read(r.join("Ch/1.png")).unwrap(),b"one");assert_eq!(fs::read(r.join("Ch/2.png")).unwrap(),b"two");fs::remove_dir_all(r).unwrap();}
#[test]fn cleanup_moves_update_catalog_by_stable_file_id(){let r=temp();fs::create_dir(r.join("Ch")).unwrap();fs::write(r.join("Ch/2.png"),b"cleanup").unwrap();save(&r,"media-index.json",&json!({"format":"studio-media-index-v1","schemaVersion":1,"projectId":"p","entries":{"[\"card\",0]":{"sourceCardId":"card","variantIndex":0,"files":[{"id":"file","relativePath":"Ch/2.png","managed":true}]}}})).unwrap();let result=organize(r.to_string_lossy().into_owned(),"p".into(),vec![json!({"from":"Ch/2.png","to":"New/3.png","type":"cleanup","entryKey":"[\"card\",0]","fileId":"file"})]).unwrap();assert_eq!(result["catalog"]["entries"]["[\"card\",0]"]["files"][0]["relativePath"],"New/3.png");assert_eq!(fs::read(r.join("New/3.png")).unwrap(),b"cleanup");fs::remove_dir_all(r).unwrap();}
}

#[cfg(test)]mod retirement_tests{use super::*;
#[test]fn stale_rough_record_cannot_move_its_replacement_cleanup(){let r=std::env::temp_dir().join(format!("ss-retire-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(r.join("Studio Link")).unwrap();save(&r,"project.json",&json!({"project":{"id":"p"},"storyboards":{}})).unwrap();crate::owned_output::write(&r,"Ch/1.png",b"rough","p","drawing:one:0").unwrap();fs::write(r.join("Ch/1.png"),b"cleanup-one").unwrap();fs::write(r.join("Ch/2.png"),b"cleanup-two").unwrap();save(&r,"media-index.json",&json!({"projectId":"p","entries":{"one":{"files":[{"id":"f1","relativePath":"Ch/1.png","managed":true}]},"two":{"files":[{"id":"f2","relativePath":"Ch/2.png","managed":true}]}}})).unwrap();let out=organize(r.to_string_lossy().into_owned(),"p".into(),vec![json!({"from":"Ch/1.png","to":"Archive/1_storyboard.png","type":"storyboard","key":"old","cardId":"one"}),json!({"from":"Ch/1.png","to":"Ch/2.png","type":"cleanup","entryKey":"one","fileId":"f1"}),json!({"from":"Ch/2.png","to":"Ch/1.png","type":"cleanup","entryKey":"two","fileId":"f2"})]).unwrap();assert_eq!(fs::read(r.join("Ch/1.png")).unwrap(),b"cleanup-two");assert_eq!(fs::read(r.join("Ch/2.png")).unwrap(),b"cleanup-one");assert_eq!(out["missing"].as_array().unwrap().len(),1);assert!(!r.join("Archive/1_storyboard.png").exists());assert!(out["outputs"]["Ch/2.png"].is_null());fs::remove_dir_all(r).unwrap();}
}

#[tauri::command]pub fn retire_storyboard_output(directory:String,project_id:String,relative_path:String,card_id:String,source_card_id:String,owner_key:Option<String>)->Result<(),String>{let root=disk::root(&directory)?;let manifest=load(&disk::subdir(&root,"Studio Link")?.join("project.json"),json!({}))?;if manifest["project"]["id"]!=project_id{return Err("Project folder belongs to another project".into())}crate::owned_output::retire(&root,&relative_path,&project_id,&card_id,&source_card_id,owner_key.as_deref())}
